from cardio_1 import a, G
# J09 — Grippe (P-02-Pneumologie), glossaire propre au cours.
if 'H1N1' not in G: a('H1N1', [('H1', 'Hémagglutinine de sous-type 1'), ('N1', 'Neuraminidase de sous-type 1')], 'Sous-type H1N1 du virus influenza A', '<p>Sous-type du virus influenza A portant l’hémagglutinine 1 et la neuraminidase 1. Il a causé la pandémie de 1918 ; le virus A(H1N1)pdm09, issu de la pandémie de 2009, circule depuis comme virus saisonnier.</p>')
if 'H2N2' not in G: a('H2N2', [('H2', 'Hémagglutinine de sous-type 2'), ('N2', 'Neuraminidase de sous-type 2')], 'Sous-type H2N2 du virus influenza A', '<p>Sous-type du virus influenza A responsable de la pandémie de 1957. Il ne circule plus chez l’être humain depuis 1968.</p>')
if 'H3N2' not in G: a('H3N2', [('H3', 'Hémagglutinine de sous-type 3'), ('N2', 'Neuraminidase de sous-type 2')], 'Sous-type H3N2 du virus influenza A', '<p>Sous-type du virus influenza A apparu lors de la pandémie de 1968 et devenu saisonnier. Les saisons où il domine sont souvent lourdes chez les personnes âgées.</p>')
if 'H5N1' not in G: a('H5N1', [('H5', 'Hémagglutinine de sous-type 5'), ('N1', 'Neuraminidase de sous-type 1')], 'Sous-type H5N1 du virus influenza A', '<p>Sous-type aviaire hautement pathogène. Les infections humaines, rares et le plus souvent liées à un contact avec des volailles, relèvent de J09 — Grippe à virus d’influenza zoonotique ou pandémique identifié.</p>')
if 'McCullers' not in G: a('McCullers', [('McCullers', 'nom propre : Jonathan A. McCullers, pédiatre et chercheur américain, auteur d’une revue de 2014 sur la surinfection bactérienne après grippe ; ce n’est pas une abréviation')], 'Jonathan A. McCullers', '<p>Auteur de la revue « The co-pathogenesis of influenza viruses with bacteria in the lung » (Nature Reviews Microbiology, 2014), qui décrit les mécanismes de la synergie entre virus influenza et bactéries.</p>')
if 'CAPSTONE-1' not in G: a('CAPSTONE-1', [('CAPSTONE-1', 'nom propre d’essai, sans développement lettre à lettre publié, suivi du numéro 1')], 'Essai CAPSTONE-1', '<p>Essai randomisé de phase 3 publié en 2018 (Hayden, New England Journal of Medicine) : baloxavir marboxil, oseltamivir ou placebo dans la grippe non compliquée de patients ambulatoires sans facteur de risque.</p>')
if 'CAPSTONE-2' not in G: a('CAPSTONE-2', [('CAPSTONE-2', 'nom propre d’essai, sans développement lettre à lettre publié, suivi du numéro 2')], 'Essai CAPSTONE-2', '<p>Essai randomisé de phase 3 publié en 2020 (Ison, Lancet Infectious Diseases) : baloxavir marboxil, oseltamivir ou placebo chez des patients ambulatoires à haut risque de complication.</p>')
if 'CENTERSTONE' not in G: a('CENTERSTONE', [('CENTERSTONE', 'nom propre d’essai, sans développement lettre à lettre publié')], 'Essai CENTERSTONE', '<p>Essai randomisé de phase 3 publié en 2025 (Monto, New England Journal of Medicine) : une dose de baloxavir marboxil chez le cas index réduisait la transmission virologiquement confirmée aux contacts domestiques par rapport au placebo.</p>')
if 'Guillain-Barré' not in G: a('Guillain-Barré', [('Guillain-Barré', 'nom propre : Georges Guillain et Jean-Alexandre Barré')], 'Syndrome de Guillain-Barré', '<p>Polyradiculonévrite aiguë inflammatoire démyélinisante, souvent postinfectieuse, qui provoque une faiblesse ascendante et une aréflexie.</p>')
if 'RT-PCR' not in G: a('RT-PCR', [('RT', 'Reverse Transcription (transcription inverse)'), ('PCR', 'Polymerase Chain Reaction (amplification en chaîne par polymérase)')], 'Amplification en chaîne par polymérase après transcription inverse', '<p>Technique de détection du génome viral : une enzyme copie l’acide ribonucléique du virus en acide désoxyribonucléique, puis chaque cycle d’amplification double le nombre de copies de la cible. Elle constitue l’examen de référence du diagnostic de grippe et distingue la grippe A de la grippe B.</p>', 'j09-rtpcr')
if 'H275Y' not in G: a('H275Y', [('H', 'Histidine (acide aminé d’origine)'), ('275', 'position 275 de la neuraminidase'), ('Y', 'Tyrosine (acide aminé de remplacement)')], 'Substitution histidine → tyrosine en position 275 de la neuraminidase', '<p>Mutation des virus H1N1 qui confère une résistance à l’oseltamivir et au péramivir ; le zanamivir et le baloxavir restent actifs.</p>')
if 'H274Y' not in G: a('H274Y', [('H', 'Histidine'), ('274', 'position 274 selon la numérotation de la neuraminidase de type 2'), ('Y', 'Tyrosine')], 'Même mutation que H275Y, autre numérotation', '<p>Notation employée dans certaines informations professionnelles ; elle désigne la même substitution que H275Y.</p>')
if 'I38T' not in G: a('I38T', [('I', 'Isoleucine (acide aminé d’origine)'), ('38', 'position 38 de la sous-unité acide de la polymérase'), ('T', 'Thréonine (acide aminé de remplacement)')], 'Substitution isoleucine → thréonine en position 38 de la polymérase', '<p>Mutation qui réduit la sensibilité au baloxavir ; elle émerge sous traitement chez 5 à 10 % des adultes traités dans les essais.</p>')
if 'M2' not in G: a('M2', [('M', 'Matrice (protéine de matrice)'), ('2', 'deuxième protéine codée par le segment de matrice')], 'Protéine M2 du virus influenza A', '<p>Canal à protons de l’enveloppe virale ; il acidifie l’intérieur du virion et permet la libération du génome. Cible des adamantanes.</p>')
if 'BLOCKSTONE' not in G: a('BLOCKSTONE', [('BLOCKSTONE', 'nom d’essai non développable lettre à lettre')], 'Essai BLOCKSTONE (baloxavir en prophylaxie familiale)', '<p>Essai randomisé japonais : dose unique de baloxavir contre placebo chez les contacts du ménage d’un cas de grippe (Ikematsu, 2020).</p>')
if 'FLAGSTONE' not in G: a('FLAGSTONE', [('FLAGSTONE', 'nom d’essai non développable lettre à lettre')], 'Essai FLAGSTONE (baloxavir chez l’hospitalisé grave)', '<p>Essai randomisé : ajout du baloxavir à un inhibiteur de la neuraminidase chez des patients hospitalisés pour grippe grave, sans bénéfice (Kumar, 2022).</p>')
if 'TIV' not in G: a('TIV', [('T', 'Trivalent'), ('I', 'Influenza'), ('V', 'Vaccine')], 'Vaccin grippal trivalent (sigle anglais du fabricant)', '<p>Vaccin grippal contenant les antigènes de trois souches : A(H1N1), A(H3N2) et B lignée Victoria.</p>')
if 'ECDC' not in G: a('ECDC', [('E', 'European'), ('C', 'Centre for'), ('D', 'Disease Prevention and'), ('C', 'Control')], 'Centre européen de prévention et de contrôle des maladies', '<p>Agence de l’Union européenne, établie à Stockholm, qui surveille les maladies infectieuses en Europe, publie avec le bureau régional de l’OMS les données de surveillance de la grippe et de la résistance aux antiviraux, et diffuse des avis scientifiques.</p>')
if 'EOLIA' not in G: a('EOLIA', [('EOLIA', 'nom propre d’essai : ECMO to Rescue Lung Injury in Severe ARDS ; acronyme non développé lettre à lettre dans ce cours')], 'Essai EOLIA', '<p>Essai randomisé publié en 2018 qui a comparé l’oxygénation par membrane extracorporelle précoce à une stratégie conventionnelle dans le syndrome de détresse respiratoire aiguë très sévère ; ses critères d’inclusion servent de référence aux recommandations de l’ESICM de 2023.</p>')
if 'Panton-Valentine' not in G: a('Panton-Valentine', [('Panton-Valentine', 'nom propre : Philip Noel Panton et Francis Valentine, qui ont décrit cette toxine ; ce n’est pas une abréviation')], 'Leucocidine de Panton-Valentine', '<p>Toxine de certaines souches de Staphylococcus aureus qui détruit les polynucléaires ; elle est associée aux pneumonies nécrosantes après grippe.</p>')
if 'Saint-Gall' not in G: a('Saint-Gall', [('Saint-Gall', 'nom propre de ville et de canton suisses ; ce n’est pas une abréviation')], 'Saint-Gall', '<p>Ville et canton de Suisse orientale ; l’Hôpital cantonal de Saint-Gall publie des directives cliniques d’infectiologie sur la plateforme guidelines.ch.</p>')
